def recover_counts(snapshot,events,target_next):
    # Own schema: (version,session,last_APPLIED_sequence,(A_count,B_count)).
    # No snapshot provenance/coherent-capture/durability is proved by this function.
    if type(snapshot) is not tuple or len(snapshot)!=4:
        raise ValueError("invalid snapshot shape")
    version,session,through,values=snapshot
    if type(version) is not int or version!=1 or type(session) is not str or session!="DAY1":
        raise ValueError("unsupported schema or session")
    if type(through) is not int or not 0<=through<=16 or type(values) is not tuple or len(values)!=2:
        raise ValueError("invalid cursor or values")
    if any(type(x) is not int or not 0<=x<=100 for x in values):
        raise ValueError("invalid count range")
    if type(target_next) is not int or not through+1<=target_next<=17:
        raise ValueError("invalid target cursor")
    if type(events) is not list or len(events)>16:
        raise ValueError("invalid bounded replay")
    for event in events:
        if type(event) is not tuple or len(event)!=3:
            raise ValueError("invalid event shape")
        sequence,symbol,delta=event
        if type(sequence) is not int or not 1<=sequence<=16 or type(symbol) is not str or symbol not in ("A","B") or type(delta) is not int or not -10<=delta<=10:
            raise ValueError("invalid event field")
    candidate=list(values)
    expected=through+1
    for sequence,symbol,delta in events:
        if sequence!=expected:
            raise ValueError("noncontiguous replay")
        index=0 if symbol=="A" else 1
        updated=candidate[index]+delta
        if not 0<=updated<=100:
            raise ValueError("count invariant failed")
        candidate[index]=updated
        expected+=1
    if expected!=target_next:
        raise ValueError("target not reached")
    return expected,tuple(candidate)

initial=(1,"DAY1",0,(10,10))
events=[(1,"A",2),(2,"B",-3),(3,"A",-1)]
full=recover_counts(initial,events,4)
snapshot=(1,"DAY1",2,(12,7))
print(full)
print(recover_counts(snapshot,events[2:],4)==full)
try:
    recover_counts(initial,events[1:],4)
except ValueError as error:
    print(error)
print(initial)
